import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z3 } from "npm:zod@^3.25.76";
var list_stars_default = defineTool3({
  name: "list_stars",
  title: "List catalog stars",
  description: "List the observer's visual star catalog, optionally filtered by constellation or a name search.",
  inputSchema: {
    constellation: z3.string().trim().min(1).optional().describe("Filter by constellation code, e.g. 'Dra'."),
    search: z3.string().trim().min(1).optional().describe("Case-insensitive star name search."),
    limit: z3.number().int().min(1).max(500).default(200).describe("Maximum number of stars to return.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ constellation, search, limit }, ctx) => {
    if (!ctx.isAuthenticated()) return unauthenticated();
    const supabase = supabaseForUser(ctx);
    let query = supabase.from("stars").select("id,name,constellation,type,aavso_code,vsnet_code,chart_id,notes,sort_order").order("constellation").order("sort_order").limit(limit ?? 200);
    if (constellation) query = query.eq("constellation", constellation);
    if (search) query = query.ilike("name", `%${search}%`);
    const { data, error } = await query;
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? []) }],
      structuredContent: { stars: data ?? [] }
    };
  }
});

