import { defineTool as defineTool12 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z12 } from "npm:zod@^3.25.76";

// src/lib/exporters/index.ts
function magOrLimit(r) {
  const m = computeMagnitude(r, r.star_name);
  return m.value == null ? null : csvSafe(m.value);
}
function csvSafe(s) {
  return s.replace(/[,\r\n]/g, " ").trim();
}
function rowDate(row, ctx) {
  if (!row.ut_time) return ctx.observedAt;
  const d = new Date(ctx.observedAt);
  applyUtTimeToDate(d, row.ut_time);
  return d;
}
function buildVSNET(rows, ctx) {
  const lines = [];
  for (const r of rows) {
    const mag = magOrLimit(r);
    if (!mag) continue;
    if (!r.vsnet_code) continue;
    const code = r.vsnet_code.trim().padEnd(8, " ");
    const dateStr = vsnetDate(rowDate(r, ctx));
    const rawNote = (r.note ?? "").trim();
    const suffix = rawNote ? ` ${rawNote}` : "";
    lines.push(`${code} ${dateStr} ${mag.padStart(5, " ")} ${ctx.obsCode}${suffix}`);
  }
  return lines.join("\n") + "\n";
}
function buildAAVSO(rows, ctx) {
  const header = [
    "#TYPE=Visual",
    `#OBSCODE=${ctx.obsCode}`,
    "#SOFTWARE=Visual-Astro (japysoft)",
    "#DELIM=,",
    "#DATE=JD",
    "#OBSTYPE=Visual"
  ].join("\n");
  const body = [];
  for (const r of rows) {
    const mag = magOrLimit(r);
    if (!mag) continue;
    if (!r.aavso_code) continue;
    const isLimit = !!(r.limit_value && r.limit_value.trim());
    const aVal = resolveCompValue(r.star_name, r.a ?? null);
    const bVal = resolveCompValue(r.star_name, r.b ?? null);
    const comp1 = isLimit ? Number.isFinite(bVal) ? bVal.toFixed(2) : csvSafe((r.limit_value ?? "").replace("<", "")) : Number.isFinite(aVal) ? aVal.toFixed(2) : csvSafe(r.a ?? "");
    const comp2 = isLimit ? "na" : Number.isFinite(bVal) ? bVal.toFixed(2) : csvSafe(r.b ?? "");
    const jd = ctx.jd + (rowDate(r, ctx).getTime() - ctx.observedAt.getTime()) / 864e5;
    const rawNote = csvSafe((r.note ?? "").trim().replace(/:/g, "Z"));
    const upper = rawNote.toUpperCase();
    const noteOut = upper === "OUTBURST" || upper === "ACTIVE" ? "Y" : rawNote || "na";
    body.push(
      [
        r.aavso_code,
        jd.toFixed(4),
        mag,
        "na",
        comp1 || "na",
        comp2 || "na",
        r.chart_id || "na",
        noteOut
      ].join(",")
    );
  }
  return header + "\n" + body.join("\n") + "\n";
}

// src/lib/mcp/tools/export-session.ts
var export_session_default = defineTool12({
  name: "export_session",
  title: "Export session",
  description: "Build the VSNET or AAVSO Visual export text for a session, exactly as the app's export dialog does.",
  inputSchema: {
    session_id: z12.string().uuid().describe("Session to export."),
    format: z12.enum(["vsnet", "aavso"]).describe("Export format."),
    obs_code: z12.string().trim().min(1).max(10).optional().describe("Observer code; defaults to the profile setting.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ session_id, format, obs_code }, ctx) => {
    if (!ctx.isAuthenticated()) return unauthenticated();
    const supabase = supabaseForUser(ctx);
    const { data: session, error } = await supabase.from("sessions").select("id,observed_at_utc,jd").eq("id", session_id).maybeSingle();
    if (error) return fail(error.message);
    if (!session) return fail("Session not found.");
    const { data: obs, error: obsErr } = await supabase.from("observations").select("a,b,pasos_a,pasos_b,limit_value,ut_time,note,row_index,stars(name,vsnet_code,aavso_code,chart_id)").eq("session_id", session_id).order("row_index");
    if (obsErr) return fail(obsErr.message);
    let code = obs_code?.trim();
    if (!code) {
      const { data: profile } = await supabase.from("profiles").select("obs_code").maybeSingle();
      code = profile?.obs_code ?? "DPV";
    }
    const observedAt = new Date(session.observed_at_utc);
    const rows = (obs ?? []).map((o) => {
      const star = o.stars;
      return {
        a: o.a,
        b: o.b,
        pasos_a: o.pasos_a,
        pasos_b: o.pasos_b,
        limit_value: o.limit_value,
        ut_time: o.ut_time,
        note: o.note,
        star_name: star?.name ?? "",
        vsnet_code: star?.vsnet_code ?? null,
        aavso_code: star?.aavso_code ?? null,
        chart_id: star?.chart_id ?? null
      };
    });
    const exportCtx = {
      observedAt,
      jd: session.jd != null ? Number(session.jd) : dateToJD(observedAt),
      obsCode: code
    };
    const text = format === "vsnet" ? buildVSNET(rows, exportCtx) : buildAAVSO(rows, exportCtx);
    return {
      content: [{ type: "text", text }],
      structuredContent: { format, obs_code: code, rows: rows.length, text }
    };
  }
});

